import gurobipy as gp
from gurobipy import GRB
projects = []
capital = {}
npv = {}
for rec in LEGACY_RECORDS:
    v = rec['values']
    pid = int(v['Project ID'])
    pname = v['Project Name']
    c = int(v['Capital (k$)'])
    vval = int(v['NPV (k$)'])
    projects.append(pid)
    capital[pid] = c
    npv[pid] = vval
if len(projects) != 110 or set(projects) != set(range(1, 111)):
    raise ValueError('Project IDs missing or duplicated in LEGACY_RECORDS.')
m = gp.Model('ProjectSelection')
x = m.addVars(projects, vtype=GRB.BINARY, lb=0, name='')
m.setObjective(gp.quicksum((npv[i] * x[i] for i in projects)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((capital[i] * x[i] for i in projects)) <= 1000, name='budget')
m.addConstr(x[4] + x[7] <= 1, name='mutual_4_7')
m.addConstr(x[6] <= x[1], name='prereq_6_1')
m.addConstr(x[10] <= x[5], name='contingent_10_5')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')